#define main v30_unused_main
#include "bdr_v30_ticketed_pipeline.cpp"
#undef main
#include <leveldb/db.h>
#include <leveldb/write_batch.h>
#include <rocksdb/db.h>
#include <rocksdb/write_batch.h>
#include <shared_mutex>

static inline uint64_t v35mix(uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);} 
static inline uint64_t v35fnv(const std::string&s){uint64_t h=1469598103934665603ULL;for(unsigned char c:s){h^=c;h*=1099511628211ULL;}return h;}
struct V35A{uint32_t rho;uint64_t fp;};
static inline V35A v35enc(const std::string&k,uint32_t M){uint64_t h0=v35mix(v35fnv(k)),h1=v35mix(h0^0xD6E8FEB86659FD93ULL),h2=v35mix(h1^0xA5A35625D3E7E5B9ULL),h3=v35mix(h2^0x9E3779B97F4A7C15ULL);return{uint32_t(h0&(M-1)),v35mix(h0^(h1<<1)^(h2>>1)^h3)};}
static uint32_t v35pow2ceil(uint64_t x){uint64_t p=1;while(p<x)p<<=1;return (uint32_t)p;}
struct V35Slot{uint64_t k=0,v=0;uint32_t d=0;bool used=false;};
class V35RH{std::vector<V35Slot>s;size_t mask;public:V35RH()=default;explicit V35RH(size_t n){reset(n);}void reset(size_t n){size_t c=8;while(double(c)*.72<double(std::max<size_t>(1,n)))c<<=1;s.assign(c,{});mask=c-1;}void put(uint64_t k,uint64_t v){size_t i=v35mix(k)&mask;V35Slot cur{k,v,0,true};for(;;){auto&x=s[i];if(!x.used){x=cur;return;}if(x.k==k){x.v=v;return;}if(x.d<cur.d)std::swap(x,cur);i=(i+1)&mask;++cur.d;}}bool get(uint64_t k,uint64_t&v)const{size_t i=v35mix(k)&mask;uint32_t d=0;for(;;){auto&x=s[i];if(!x.used||x.d<d)return false;if(x.k==k){v=x.v;return true;}i=(i+1)&mask;++d;}}};
struct V35Shard{mutable std::shared_mutex mu;V35RH rh;};
class V35Index{uint32_t M;std::vector<std::unique_ptr<V35Shard>>p;public:V35Index(size_t expected,size_t writes):M(v35pow2ceil(std::max<uint64_t>(64,(expected+255)/256))),p(M){size_t per=(expected+writes)/M+64;for(auto&x:p){x=std::make_unique<V35Shard>();x->rh.reset(per);}}void put(const std::string&k,uint64_t v){auto a=v35enc(k,M);auto&x=*p[a.rho];std::unique_lock lk(x.mu);x.rh.put(a.fp,v);}bool get(const std::string&k,uint64_t&v)const{auto a=v35enc(k,M);auto&x=*p[a.rho];std::shared_lock lk(x.mu);return x.rh.get(a.fp,v);}uint32_t parts()const{return M;}};
static std::string BK(size_t i){return "B_"+std::to_string(i);}static std::string WK(size_t i){return "W_"+std::to_string(i);}static std::string VV(size_t i){return "V_"+std::to_string(i);} 
struct V35R{std::string engine,profile;double ops_s;uint64_t read_err=0,write_err=0;size_t writes=0;};
static size_t choose_read(uint64_t&rng,size_t base,bool hot){rng=v35mix(rng);if(!hot)return rng%base;uint64_t q=rng%100; rng=v35mix(rng);return q<80?rng%std::max<size_t>(1,base/100):rng%base;}
static bool choose_write(uint64_t&rng,int write_pct){rng=v35mix(rng);return int(rng%100)<write_pct;}

static V35R run_bdr35(size_t base,size_t ops,int threads,int write_pct,bool hot){std::filesystem::remove("v35.bdr");size_t maxw=ops;V35Index idx(base,maxw);for(size_t i=0;i<base;++i)idx.put(BK(i),i);TicketWal wal("v35.bdr",maxw*96+4096,512);std::atomic<size_t>nextop{0},nextw{0};std::atomic<uint64_t>re{0};auto a=Clock::now();std::vector<std::thread>ts;for(int t=0;t<threads;++t)ts.emplace_back([&,t]{uint64_t rng=0xB0D35000ULL+t;std::vector<std::pair<std::string,uint64_t>>pend;pend.reserve(128);uint64_t last=0;auto flush=[&]{if(pend.empty())return;wal.wait(last);for(auto&x:pend)idx.put(x.first,x.second);pend.clear();};for(;;){size_t n=nextop.fetch_add(1);if(n>=ops)break;if(choose_write(rng,write_pct)){size_t wi=nextw.fetch_add(1);auto k=WK(wi);last=wal.submit(k,VV(wi));pend.emplace_back(k,wi);if(pend.size()>=128)flush();}else{size_t ri=choose_read(rng,base,hot);uint64_t v=~0ull;if(!idx.get(BK(ri),v)||v!=ri)re++;}}flush();});for(auto&t:ts)t.join();double sec=std::chrono::duration<double>(Clock::now()-a).count();size_t nw=nextw.load();uint64_t we=0;for(size_t i=0;i<nw;++i){uint64_t v=~0ull;if(!idx.get(WK(i),v)||v!=i)we++;}return{"BDR-v35",hot?"hot":"uniform",ops/sec,re.load(),we,nw};}

static V35R run_level35(size_t base,size_t ops,int threads,int write_pct,bool hot){std::filesystem::remove_all("v35.level");leveldb::DB*d=nullptr;leveldb::Options o;o.create_if_missing=true;if(!leveldb::DB::Open(o,"v35.level",&d).ok())throw std::runtime_error("level open");leveldb::WriteOptions init;for(size_t i=0;i<base;i+=1000){leveldb::WriteBatch b;for(size_t j=i;j<std::min(base,i+1000);++j)b.Put(BK(j),std::to_string(j));d->Write(init,&b);}leveldb::ReadOptions ro;leveldb::WriteOptions wo;wo.sync=true;std::atomic<size_t>nextop{0},nextw{0};std::atomic<uint64_t>re{0},we{0};auto a=Clock::now();std::vector<std::thread>ts;for(int t=0;t<threads;++t)ts.emplace_back([&,t]{uint64_t rng=0x1EVE3500ULL+t;leveldb::WriteBatch b;size_t bn=0;auto flush=[&]{if(!bn)return;if(!d->Write(wo,&b).ok())we+=bn;b.Clear();bn=0;};for(;;){size_t n=nextop.fetch_add(1);if(n>=ops)break;if(choose_write(rng,write_pct)){size_t wi=nextw.fetch_add(1);b.Put(WK(wi),std::to_string(wi));if(++bn>=128)flush();}else{size_t ri=choose_read(rng,base,hot);std::string v;if(!d->Get(ro,BK(ri),&v).ok()||v!=std::to_string(ri))re++;}}flush();});for(auto&t:ts)t.join();double sec=std::chrono::duration<double>(Clock::now()-a).count();delete d;return{"LevelDB",hot?"hot":"uniform",ops/sec,re.load(),we.load(),nextw.load()};}

static V35R run_rocks35(size_t base,size_t ops,int threads,int write_pct,bool hot){std::filesystem::remove_all("v35.rocks");rocksdb::DB*d=nullptr;rocksdb::Options o;o.create_if_missing=true;if(!rocksdb::DB::Open(o,"v35.rocks",&d).ok())throw std::runtime_error("rocks open");rocksdb::WriteOptions init;for(size_t i=0;i<base;i+=1000){rocksdb::WriteBatch b;for(size_t j=i;j<std::min(base,i+1000);++j)b.Put(BK(j),std::to_string(j));d->Write(init,&b);}rocksdb::ReadOptions ro;rocksdb::WriteOptions wo;wo.sync=true;std::atomic<size_t>nextop{0},nextw{0};std::atomic<uint64_t>re{0},we{0};auto a=Clock::now();std::vector<std::thread>ts;for(int t=0;t<threads;++t)ts.emplace_back([&,t]{uint64_t rng=0xA0C53500ULL+t;rocksdb::WriteBatch b;size_t bn=0;auto flush=[&]{if(!bn)return;if(!d->Write(wo,&b).ok())we+=bn;b.Clear();bn=0;};for(;;){size_t n=nextop.fetch_add(1);if(n>=ops)break;if(choose_write(rng,write_pct)){size_t wi=nextw.fetch_add(1);b.Put(WK(wi),std::to_string(wi));if(++bn>=128)flush();}else{size_t ri=choose_read(rng,base,hot);std::string v;if(!d->Get(ro,BK(ri),&v).ok()||v!=std::to_string(ri))re++;}}flush();});for(auto&t:ts)t.join();double sec=std::chrono::duration<double>(Clock::now()-a).count();delete d;return{"RocksDB",hot?"hot":"uniform",ops/sec,re.load(),we.load(),nextw.load()};}

int main(int argc,char**argv){size_t base=argc>1?std::stoull(argv[1]):500000,ops=argc>2?std::stoull(argv[2]):200000;int threads=argc>3?std::stoi(argv[3]):8;std::cout<<"engine,profile,write_pct,threads,base,ops,throughput_ops_s,writes,read_errors,write_errors\n";for(int wp:{10,50})for(bool hot:{false,true}){V35R rows[]={run_bdr35(base,ops,threads,wp,hot),run_level35(base,ops,threads,wp,hot),run_rocks35(base,ops,threads,wp,hot)};for(auto&r:rows){std::cout<<r.engine<<','<<r.profile<<','<<wp<<','<<threads<<','<<base<<','<<ops<<','<<r.ops_s<<','<<r.writes<<','<<r.read_err<<','<<r.write_err<<"\n";if(r.read_err||r.write_err)return 2;}}return 0;}
